<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<title>Lotte World Tower Design Process • grok-4.3</title>
<style>
body { margin:0; font-family: system-ui, -apple-system, sans-serif; background:#0a0a0a; color:#ddd; }
header { background:#111; padding:12px 20px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid #333; }
h1 { margin:0; font-size:22px; }
.model-name { background:#222; padding:4px 12px; border-radius:4px; font-size:13px; color:#0ff; }
.container { max-width:1400px; margin:0 auto; padding:20px; }
.section { margin-bottom:40px; }
h2 { font-size:18px; border-bottom:1px solid #333; padding-bottom:8px; }
.grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
@media (max-width:900px){ .grid { grid-template-columns:1fr; } }
canvas { background:#111; border:1px solid #333; border-radius:6px; display:block; width:100%; }
.controls { display:flex; gap:8px; flex-wrap:wrap; margin:12px 0; }
button { background:#222; color:#ddd; border:1px solid #444; padding:8px 16px; border-radius:4px; cursor:pointer; font-size:14px; }
button.active { background:#0ff; color:#000; }
.drawing { background:#111; padding:16px; border-radius:6px; }
svg { width:100%; height:auto; }
.info { font-size:13px; color:#888; line-height:1.5; }
</style>
</head>
<body>
<header>
  <h1>롯데월드타워 설계 과정</h1>
  <div class="model-name">grok-4.3</div>
</header>

<div class="container">

  <!-- 2D Drawings -->
  <div class="section">
    <h2>설계 도면 (개념 재구성)</h2>
    <div class="grid">
      <!-- Site Plan -->
      <div class="drawing">
        <h3>배치도 (Site Plan)</h3>
        <svg width="100%" height="220" viewBox="0 0 400 220">
          <rect x="40" y="30" width="320" height="160" fill="#1a1a1a" stroke="#555"/>
          <rect x="140" y="70" width="120" height="80" fill="none" stroke="#0ff" stroke-width="2"/>
          <text x="200" y="115" fill="#0ff" font-size="12" text-anchor="middle">타워 footprint</text>
          <circle cx="200" cy="110" r="4" fill="#0ff"/>
          <text x="200" y="200" fill="#888" font-size="11" text-anchor="middle">개념적 배치 • 실제 치수 아님</text>
        </svg>
        <div class="info">송파구 잠실동 부지. 타워 중심 위치 표시. (개념)</div>
      </div>

      <!-- Floor Plan -->
      <div class="drawing">
        <h3>기준층 평면도 (Typical Floor)</h3>
        <svg width="100%" height="220" viewBox="0 0 400 220">
          <rect x="80" y="40" width="240" height="140" fill="none" stroke="#0ff" stroke-width="3"/>
          <rect x="100" y="55" width="200" height="110" fill="#222" stroke="#555"/>
          <line x1="200" y1="55" x2="200" y2="165" stroke="#0ff" stroke-width="1"/>
          <text x="200" y="120" fill="#0ff" font-size="11" text-anchor="middle">코어</text>
          <text x="200" y="200" fill="#888" font-size="11" text-anchor="middle">상층으로 갈수록 축소 (추정)</text>
        </svg>
        <div class="info">위로 갈수록 면적 축소. 한국 도자기 곡선 반영 (KPF 개념)</div>
      </div>

      <!-- Elevation -->
      <div class="drawing">
        <h3>입면도 (Elevation)</h3>
        <svg width="100%" height="220" viewBox="0 0 400 220">
          <polygon points="200,20 320,200 80,200" fill="none" stroke="#0ff" stroke-width="3"/>
          <line x1="200" y1="20" x2="200" y2="200" stroke="#555" stroke-dasharray="4"/>
          <text x="200" y="215" fill="#888" font-size="11" text-anchor="middle">555m (123층) • 상부 테이퍼</text>
        </svg>
        <div class="info">도자기 선을 모티브로 한 부드러운 곡선 테이퍼 (개념)</div>
      </div>

      <!-- Section -->
      <div class="drawing">
        <h3>단면도 (Section)</h3>
        <svg width="100%" height="220" viewBox="0 0 400 220">
          <polygon points="200,20 310,200 90,200" fill="#1a1a1a" stroke="#0ff" stroke-width="2"/>
          <rect x="170" y="30" width="60" height="160" fill="#333"/>
          <text x="200" y="215" fill="#888" font-size="11" text-anchor="middle">코어 + 외피 구조 (개념)</text>
        </svg>
        <div class="info">모든 치수는 공개 자료 기반 개념 추정치입니다.</div>
      </div>
    </div>
  </div>

  <!-- Design Stages -->
  <div class="section">
    <h2>설계 단계별 3D 형상</h2>
    <div class="controls">
      <button onclick="showStage(0)" class="active" id="btn0">1. 초기 개념</button>
      <button onclick="showStage(1)" id="btn1">2. 형태 정제</button>
      <button onclick="showStage(2)" id="btn2">3. 도자기 곡선 적용</button>
      <button onclick="showStage(3)" id="btn3">4. 완성 모델</button>
    </div>

    <canvas id="stageCanvas" width="800" height="520" style="max-width:100%; height:auto;"></canvas>
    <div class="info" style="margin-top:8px;">
      마우스 드래그: 회전 | 휠: 확대/축소 | 더블클릭: 시점 초기화<br>
      모든 모델은 개념적이며 실제 구조 도면이 아닙니다.
    </div>
  </div>

</div>

<script>
// Simple 3D-like renderer using Canvas 2D
const canvas = document.getElementById('stageCanvas');
const ctx = canvas.getContext('2d');

let rotation = 0;
let zoom = 1.0;
let isDragging = false;
let lastX = 0;

function drawTower(stage, rot, z) {
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const cx = canvas.width / 2;
  const cy = canvas.height / 2 + 40;
  const scale = 1.8 * z;

  ctx.strokeStyle = '#0ff';
  ctx.lineWidth = 1.5;

  // Tower base width and height
  const baseW = 110 * scale;
  const topW = (stage === 0) ? 70 : (stage === 1) ? 55 : (stage === 2) ? 42 : 35;
  const h = 380 * scale;

  // Simple perspective projection
  const angle = rot * Math.PI / 180;

  // Draw 4 sides with rotation
  const points = [];
  for (let i = 0; i < 4; i++) {
    const a = angle + i * Math.PI / 2;
    const x1 = cx + Math.cos(a) * baseW;
    const y1 = cy;
    const x2 = cx + Math.cos(a) * topW;
    const y2 = cy - h;
    points.push({x1, y1, x2, y2});
  }

  // Draw sides
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    const p = points[i];
    const p2 = points[(i+1)%4];
    ctx.moveTo(p.x1, p.y1);
    ctx.lineTo(p.x2, p.y2);
    ctx.lineTo(p2.x2, p2.y2);
    ctx.lineTo(p2.x1, p2.y1);
    ctx.closePath();
  }
  ctx.stroke();

  // Vertical edges
  for (let i = 0; i < 4; i++) {
    const p = points[i];
    ctx.beginPath();
    ctx.moveTo(p.x1, p.y1);
    ctx.lineTo(p.x2, p.y2);
    ctx.stroke();
  }

  // Floor lines (conceptual)
  ctx.strokeStyle = '#444';
  ctx.lineWidth = 0.8;
  const floors = (stage === 3) ? 12 : 8;
  for (let f = 1; f < floors; f++) {
    const t = f / floors;
    const w = baseW * (1-t) + topW * t;
    ctx.beginPath();
    for (let i = 0; i < 4; i++) {
      const a = angle + i * Math.PI / 2;
      const x = cx + Math.cos(a) * w;
      const y = cy - h * t;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();
  }

  // Stage label
  ctx.fillStyle = '#0ff';
  ctx.font = '14px system-ui';
  ctx.fillText(['Initial Taper', 'Form Refinement', 'Pottery Curve', 'Final Model'][stage], 20, 30);
}

function showStage(stage) {
  // Update buttons
  for (let i = 0; i < 4; i++) {
    document.getElementById('btn' + i).classList.remove('active');
  }
  document.getElementById('btn' + stage).classList.add('active');

  // Redraw
  drawTower(stage, rotation, zoom);
}

// Mouse controls
canvas.addEventListener('mousedown', (e) => {
  isDragging = true;
  lastX = e.clientX;
});

window.addEventListener('mouseup', () => isDragging = false);

window.addEventListener('mousemove', (e) => {
  if (!isDragging) return;
  rotation += (e.clientX - lastX) * 0.6;
  lastX = e.clientX;
  const activeBtn = document.querySelector('.controls button.active');
  const stage = activeBtn ? parseInt(activeBtn.id.replace('btn','')) : 3;
  drawTower(stage, rotation, zoom);
});

canvas.addEventListener('wheel', (e) => {
  e.preventDefault();
  zoom = Math.max(0.5, Math.min(2.5, zoom + (e.deltaY < 0 ? 0.1 : -0.1)));
  const activeBtn = document.querySelector('.controls button.active');
  const stage = activeBtn ? parseInt(activeBtn.id.replace('btn','')) : 3;
  drawTower(stage, rotation, zoom);
});

canvas.addEventListener('dblclick', () => {
  rotation = 0;
  zoom = 1.0;
  const activeBtn = document.querySelector('.controls button.active');
  const stage = activeBtn ? parseInt(activeBtn.id.replace('btn','')) : 3;
  drawTower(stage, rotation, zoom);
});

// Touch support
canvas.addEventListener('touchstart', (e) => {
  isDragging = true;
  lastX = e.touches[0].clientX;
});
canvas.addEventListener('touchend', () => isDragging = false);
canvas.addEventListener('touchmove', (e) => {
  if (!isDragging) return;
  rotation += (e.touches[0].clientX - lastX) * 0.6;
  lastX = e.touches[0].clientX;
  const activeBtn = document.querySelector('.controls button.active');
  const stage = activeBtn ? parseInt(activeBtn.id.replace('btn','')) : 3;
  drawTower(stage, rotation, zoom);
});

// Initial render
drawTower(3, 25, 1.0);
document.getElementById('btn3').classList.add('active');
</script>
</body>
</html>
